function countPinnedSlices(nums: number[], lo: number, hi: number): number {
  let count = 0;
  for (let s = 0; s < nums.length; s++) {
    let mn = Infinity, mx = -Infinity;
    for (let e = s; e < nums.length; e++) {
      if (nums[e] < lo || nums[e] > hi) break;
      mn = Math.min(mn, nums[e]);
      mx = Math.max(mx, nums[e]);
      if (mn === lo && mx === hi) count++;
    }
  }
  return count;
}

