function countPinnedSlices(nums: number[], lo: number, hi: number): number {
  let lastBad = -1, lastLo = -1, lastHi = -1, count = 0;
  for (let i = 0; i < nums.length; i++) {
    const x = nums[i];
    if (x < lo || x > hi) lastBad = i;
    if (x === lo) lastLo = i;
    if (x === hi) lastHi = i;
    count += Math.max(0, Math.min(lastLo, lastHi) - lastBad);
  }
  return count;
}

